#!/usr/bin/env python3
"""Turn components/zlink/test/zlink_vectors.json (generated by ai_stack) into a C header for test_host.

    gen_vectors_h.py <zlink_vectors.json> <out.h>

Each vector becomes a `zv_vector_t` whose union holds the C message struct built from the JSON "fields", so the
test can (a) pack the fields with the C codec and compare to payload_hex/frame_hex and (b) decode frame_hex.
If the JSON is missing the header defines ZV_HAVE_VECTORS 0 and the test is skipped with a message.
"""
import json
import os
import sys

TYPES = {0x01: "hello", 0x02: "hello_ack", 0x03: "ping", 0x04: "pong", 0x10: "joint_targets",
         0x11: "traj_chunk", 0x12: "stream_start", 0x13: "stream_end", 0x30: "state", 0x40: "cmd", 0x41: "ack",
         # v1.1
         0x22: "camera_frame", 0x42: "calib_report", 0x70: "face_set", 0x71: "face_params", 0x72: "face_track",
         0x73: "display_image", 0x74: "display_text", 0x75: "display_mode_msg"}
# JSON field name -> C field name, where they differ
RENAME = {"state": {"q_meas_cdeg": "q_meas_cdeg", "q_cmd_cdeg": "q_cmd_cdeg"}}


def c_array(xs):
    return "{" + ", ".join(str(int(x)) for x in xs) + "}"


def c_str(t):
    return '"' + "".join(ch if 32 <= ord(ch) < 127 and ch not in '"\\' else "\\x%02x" % ord(ch) for ch in t) + '"'


def c_fields(msg, f, name, payload_len):
    out = []
    pre = []
    if msg == "state" and payload_len == 88:
        out.append(".legacy_88 = 1")
    for k, v in f.items():
        if k == "data_hex":
            data = bytes.fromhex(v)
            if data:
                pre.append(f"static const uint8_t zv_{name}_data[] = {c_array(data)};")
                out.append(f".data = zv_{name}_data, .n_data = {len(data)}")
            continue
        if msg == "traj_chunk" and k == "frames":
            frames = ", ".join("{.dt_ms = %d, .q_cdeg = %s}" % (fr["dt_ms"], c_array(fr["q_cdeg"])) for fr in v)
            out.append(f".n_frames = {len(v)}, .frames = {{{frames}}}")
            continue
        if msg == "hello_ack" and k == "name":
            out.append(f'.name = "{v}"')
            continue
        if msg == "display_text" and k == "text":
            out.append(f".text = {c_str(v)}, .n_text = {len(v.encode())}")
            continue
        if msg == "face_params" and k == "params":
            items = ", ".join("{.id = %d, .value = %sf}" % (q["id"], repr(float(q["value"]))) for q in v)
            out.append(f".n = {len(v)}, .params = {{{items}}}")
            continue
        if msg == "face_track" and k == "keys":
            items = ", ".join("{.t_ms = %d, .emotion = %d, .intensity = %d, .blend_ms = %d}"
                              % (q["t_ms"], q["emotion"], q["intensity"], q["blend_ms"]) for q in v)
            out.append(f".n = {len(v)}, .keys = {{{items}}}")
            continue
        if msg == "calib_report" and k == "joints":
            items = ", ".join("{.zero_ticks = %d, .sign = %d, .ticks_per_rev = %d}"
                              % (q["zero_ticks"], q["sign"], q["ticks_per_rev"]) for q in v)
            out.append(f".joints = {{{items}}}")
            continue
        ck = RENAME.get(msg, {}).get(k, k)
        out.append(f".{ck} = {c_array(v) if isinstance(v, list) else int(v)}")
    return pre, ", ".join(out)


def main():
    src, dst = sys.argv[1], sys.argv[2]
    lines = ["/* GENERATED by test_host/gen_vectors_h.py from zlink_vectors.json - do not edit. */",
             "#pragma once", '#include "zlink.h"', ""]
    if not os.path.exists(src):
        lines += ["#define ZV_HAVE_VECTORS 0", f'#define ZV_SOURCE "{src}"']
        open(dst, "w").write("\n".join(lines) + "\n")
        return 0
    d = json.load(open(src))
    union = ["typedef struct {", "    const char *name;", "    uint8_t type;", "    uint16_t seq;",
             "    const char *payload_hex;", "    const char *frame_hex;", "    union {"]
    union += [f"        zlink_{m}_t {m};" for m in sorted(set(TYPES.values()))]
    union += ["    } u;", "} zv_vector_t;", ""]
    pre_all, rows = [], []
    for v in d["vectors"]:
        msg = TYPES.get(v["type"])
        if msg is None:
            sys.exit(f"vector {v['name']}: type 0x{v['type']:02x} unknown to the generator")
        pre, init = c_fields(msg, v["fields"], v["name"], len(v["payload_hex"]) // 2)
        pre_all += pre
        rows.append(f'    {{"{v["name"]}", 0x{v["type"]:02x}, {v["seq"]}, "{v["payload_hex"]}", "{v["frame_hex"]}", '
                    f".u.{msg} = {{{init}}}}},")
    crc = d["crc_check"]
    lines += ["#define ZV_HAVE_VECTORS 1", f'#define ZV_CRC_INPUT "{crc["input_ascii"]}"',
              f"#define ZV_CRC_VALUE {crc['crc16']}u", ""] + union + pre_all + [
              "static const zv_vector_t zv_vectors[] = {"] + rows + ["};",
              "#define ZV_N (sizeof(zv_vectors) / sizeof(zv_vectors[0]))"]
    open(dst, "w").write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
